    /// <para>Binds <c>SDL_GetAtomicPointer</c>.</para>
    /// <para>*<b>Note: If you don't know what this function is for, you shouldn't use it!</b>*</para>
    /// <para>Thread safety: It is safe to call this function from any thread.</para>
    /// <para>This function is available since SDL 3.2.0.</para>
    /// <para>See also: <c>SDL_CompareAndSwapAtomicPointer</c>, <c>SDL_SetAtomicPointer</c>.</para>
    /// </remarks>
    /// <param name="a">a pointer to a pointer.</param>
    /// <returns>the current value of a pointer.</returns>
    [LibraryImport("jade_native", EntryPoint = "SDL_GetAtomicPointer")]
    [UnmanagedCallConv(CallConvs = [typeof(CallConvCdecl)])]
    public static partial void* GetAtomicPointer(void** a);
}
